import json
import httpx

API = "/services/data/v66.0"        # use the org's current version (see /services/data)
APPROVAL_LIMIT = 50                 # bigger batches need a named person's approval

# Stand-in for a Salesforce SANDBOX: upsert by external id creates (201) or updates (204)
crm = {}
def sandbox(request: httpx.Request) -> httpx.Response:
    ext_id = request.url.path.rsplit("/", 1)[-1]
    created = ext_id not in crm
    crm[ext_id] = {**crm.get(ext_id, {}), **json.loads(request.content)}
    return httpx.Response(201 if created else 204)

client = httpx.Client(base_url="https://yourorg--uat.sandbox.my.salesforce.com",
                      transport=httpx.MockTransport(sandbox))

def push(changes, dry_run=True, approved_by=None):
    if len(changes) > APPROVAL_LIMIT and not approved_by:
        raise PermissionError(f"{len(changes)} changes need approval first")
    results = {"created": 0, "updated": 0, "would_change": 0}
    for c in changes:
        if dry_run:
            results["would_change"] += 1      # show the plan, touch nothing
            continue
        # Upsert on OUR key (Plant_Id__c), so a retry never makes a duplicate record
        r = client.patch(f"{API}/sobjects/Account/Plant_Id__c/{c['plant_id']}",
                         json={"Name": c["name"], "Risk_Score__c": c["risk"]})
        r.raise_for_status()
        results["created" if r.status_code == 201 else "updated"] += 1
    return results

def reconcile(source):
    # Daily check: does the CRM now hold exactly what we meant to write?
    wrong = [c["plant_id"] for c in source
             if crm.get(c["plant_id"], {}).get("Risk_Score__c") != c["risk"]]
    return {"checked": len(source), "mismatched": wrong}

changes = [{"plant_id": "PL-001", "name": "Riverside", "risk": 0.82},
           {"plant_id": "PL-002", "name": "Hilltop", "risk": 0.15}]
print(push(changes))                      # dry run first
print(push(changes, dry_run=False))       # real write to the sandbox
print(push(changes, dry_run=False))       # retry: updates, no duplicates
print(len(crm), "records;", reconcile(changes))
try:
    push(changes * 30, dry_run=False)     # 60 changes, nobody approved
except PermissionError as e:
    print("blocked:", e)

# Output:
# {'created': 0, 'updated': 0, 'would_change': 2}
# {'created': 2, 'updated': 0, 'would_change': 0}
# {'created': 0, 'updated': 2, 'would_change': 0}
# 2 records; {'checked': 2, 'mismatched': []}
# blocked: 60 changes need approval first
